// Mock Auth0.js SDK - returns instant guest login
(function(){
  var MOCK_TOKEN = "eyJhbGciOiJub25lIn0.eyJzdWIiOiJndWVzdHwwMDAxIiwibmFtZSI6Ikd1ZXN0IiwiaXNHdWVzdCI6dHJ1ZX0.";
  var MOCK_SESSION = {
    accessToken: MOCK_TOKEN,
    idToken: MOCK_TOKEN,
    idTokenPayload: { sub: "guest|0001", name: "Guest", isGuest: true },
    expiresIn: 86400,
    tokenType: "Bearer",
    scope: "openid profile email"
  };
  function WebAuth(opts) {
    this.opts = opts || {};
  }
  WebAuth.prototype.authorize = function(opts, cb) {
    if (typeof opts === "function") { cb = opts; }
    if (cb) setTimeout(function(){ cb(null, MOCK_SESSION); }, 50);
  };
  WebAuth.prototype.checkSession = function(opts, cb) {
    if (typeof opts === "function") { cb = opts; }
    setTimeout(function(){ cb(null, MOCK_SESSION); }, 50);
  };
  WebAuth.prototype.parseHash = function(opts, cb) {
    if (typeof opts === "function") { cb = opts; }
    if (cb) setTimeout(function(){ cb(null, null); }, 50);
  };
  WebAuth.prototype.logout = function() {};
  WebAuth.prototype.client = {
    userInfo: function(token, cb){ if(cb) cb(null, {sub:"guest|0001",name:"Guest"}); },
    login: function(opts, cb){ if(cb) cb(null, MOCK_SESSION); }
  };
  WebAuth.prototype.getSSOData = function(withActiveDirectories, cb){
    if (typeof withActiveDirectories === "function") { cb = withActiveDirectories; }
    if (cb) cb(null, { sso: false });
  };
  window.auth0 = window.auth0 || {};
  window.auth0.WebAuth = WebAuth;
  console.log("[SG] auth0.js mocked");
})();